function avgColor(pixels){ var r=0,g=0,b=0; for(var i=0;i<pixels.length;i++){r+=pixels[i][0];g+=pixels[i][1];b+=pixels[i][2];} var n=pixels.length||1; return [Math.round(r/n),Math.round(g/n),Math.round(b/n)]; }
function medianCut(pixels, depth){
  if(depth===0 || pixels.length<=1) return pixels;
  var ch=0, maxR=0;
  for(var c=0;c<3;c++){ var mn=255,mx=0; for(var i=0;i<pixels.length;i++){ var v=pixels[i][c]; if(v<mn)mn=v; if(v>mx)mx=v; } if(mx-mn>maxR){maxR=mx-mn;ch=c;} }
  var arr=pixels.slice().sort(function(a,b){return a[ch]-b[ch];});
  var mid=arr.length>>1;
  return medianCut(arr.slice(0,mid),depth-1).concat(medianCut(arr.slice(mid),depth-1));
}
function extractPalette(pixels, n){
  var depth=Math.max(1, Math.ceil(Math.log(n)/Math.log(2)));
  var leaves=medianCut(pixels.slice(), depth);
  var out=[]; var per=Math.max(1, Math.floor(leaves.length/n));
  for(var i=0;i<n;i++){ var seg=leaves.slice(i*per,(i+1)*per); if(seg.length) out.push(avgColor(seg)); }
  while(out.length<n) out.push(out[out.length-1]||[0,0,0]);
  return out;
}
